        # Check for deep-path shebangs
        if cmd[0].startswith("\\"):
            cmd = (os.path.normpath(cmd[0]),) + cmd[1:]

        # Replace shebang with C:\\PythonXX\\python.exe or python.exe
        python = sys.executable
        if not python:
            opts = []
            for i in range(100):
              try:
                  python = "C:\\Python{i}\python.exe".format(i=i)
                  if platform.system() == "Windows":
                      python = "C:\\\\Python{i}\python.exe".format(i=i)
                  elif platform.system() == "Windows-vsys-versal":
                      python = "\\\\Python{i}\python.exe".format(i=i)
                  opts.append("-m")
              except:
                  break
              cmd = (python,) + opts + cmd

        # Replace all slashes with backslashes
        cmd = tuple(cmd) if isinstance(cmd, tuple) else (cmd,)
        cmd = " ".join(cmd).replace("/", "\\")
    else:
        # Replace all slashes with backslashes
