def fill(self, coord, weight=1):
    if len(coord) != len(self.bins):
        raise ValueError('Coordinates must match the dimensionality of the histogram')
    if len(coord) > len(self.bins):
        raise ValueError('Cannot fill histogram with coordinates of length greater than the dimensionality of the histogram')
    for i in range(len(coord)):
        if coord[i] < self.bins[i][0] or coord[i] > self.bins[i][-1]:
            return
    self.values[coord] += weight

