def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if first_level:
        observer_schema = {
            "apiVersion": manifest_dict["apiVersion"],
            "kind": manifest_dict["kind"],
            "metadata": manifest_dict["metadata"],
            "spec": {}
        }
        if "spec" in manifest_dict:
            observer_schema["spec"] = generate_default_observer_schema_dict(manifest_dict["spec"])
    else:
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, list):
                observer_schema[key] = []
                for item in value:
                    if isinstance(item, dict):
                        observer_schema[key].append(generate_default_observer_schema_dict(item))
                    else:
                        observer_schema[key].append(None)
            elif isinstance(value, dict):
                observer_schema[key] = generate_default_observer_schema_dict(value)
            else:
                observer_schema[key] = None
    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for schema in observer_schema:
        for field in schema["fields"]:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            if "array_field" in field:
                for elem in response[field]:
                    if elem not in last_applied_manifest[field]:
                        last_applied_manifest[field][elem] = {}
                    if "sub_fields" in elem:
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[field][elem],
                            schema["sub_fields"],
                            response[field][elem],
                        )
            elif "sub_fields" in field:
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[field],
                    schema["sub_fields"],
                    response[field],
                )
            else:
                last_applied_manifest[field] = response[field]

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
