def extract_number_and_supplment_from_issue_element(issue):
    pattern = re.compile(r"<issue>([\w\s\.]+)</issue>")
    match = pattern.search(issue)
    if match:
        issue = match.group(1)
    else:
        return None
    match = re.search(r"([\d]+( Suppl[\d \.]*)*)", issue)
    if match:
        number = match.group(1)
        suppl = match.group(2)
        if suppl:
            return (number, suppl.strip())
        else:
            return (number, None)
    else:
        match = re.search(r"([\d]+( suppl[\d \.]*)*)", issue)
        if match:
            number = match.group(1)
            suppl = match.group(2)
            if suppl:
                return (number, suppl.strip())
            else:
                return (number, None)
        else:
            return None

