def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base
    if padding is not None:
        result.extend(['0'] * padding)
    result.reverse()
    return ''.join(result)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        current_cls = queue.pop()
        seen.add(current_cls)

        for child in current_cls.__subclasses__():
            if child not in seen:
                queue.append(child)

    return seen

