def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    # Split the frequency string into two parts, the number and the unit
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency string: {}".format(frequency))

    # Convert the number to an integer
    number = int(parts[0])

    # Calculate the corresponding datetime.timedelta based on the unit of time
    if parts[1] == "minutes":
        return datetime.timedelta(minutes=number)
    elif parts[1] == "days":
        return datetime.timedelta(days=number)
    elif parts[1] == "weeks":
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError("Invalid unit of time: {}".format(parts[1]))

