        elif arg.default is NO_DEFAULT and self.spec is not None:
            spec_defaults[arg.name] = self.spec.get(arg.name, NO_DEFAULT)
        elif self.config is not None:
            spec_defaults[arg.name] = self.get_config_default(arg.name)
    return spec_defaults

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = []
    for arg, value in answer_file_args.items():
        if arg in cli_args and value != cli_args[arg]:
            deprecated_args.append((arg, value, cli_args[arg]))

    if deprecated_args:
        print("Deprecated arguments:")
        for arg, value, replacement in deprecated_args:
            print(f"  - {arg}: {value} is deprecated in favor of {replacement}")

