def get_silent_args(args):
    silenced = set()
    for i in range(len(args)):
        if args[i].startswith("-"):
            silenced.add(args[i].replace("-", ""))
    return list(silenced)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Check if all the required arguments have been provided
    for arg in self.args_spec:
        if arg in args:
            continue
        if arg.default is None:
            raise ArgumentError('Missing required argument: {}'.format(arg))
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if args is not None:
        for arg in args:
            if len(str(arg)) > self.length:
                raise ValueError("The argument's value is longer than the specified length.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    try:
        return any(args in choices for choices in self.argspec.choices)
    except AttributeError:
        return False

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) < 1:
        raise TypeError("at least one argument is required")
    if len(args) > 2:
        raise TypeError("only one or two arguments are allowed")
    if len(args) == 1:
        if not isinstance(args[0], numbers.Real):
            raise TypeError("first argument must be a real number")
    elif len(args) == 2:
        if not (isinstance(args[0], numbers.Real) and isinstance(args[1], numbers.Real)):
            raise TypeError("both arguments must be real numbers")
        if args[0] > args[1]:
            raise ValueError("first argument must be less than or equal to second argument")
    return args

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--'):
            if arg in self.control_args_list:
                control_args[arg.removeprefix('--')] = args[arg]
            elif arg in self.custom_args_list:
                custom_args[arg.removeprefix('--')] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars:
        if not isinstance(extra_vars, list):
            raise ValueError("Unable to merge extra-vars: List expected")
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[str(var)] = {}
            else:
                vars_dict[str(var)].update({})
    return vars_dict

