def _convert_non_cli_args(self, parser_name, values_dict):
    parser = getattr(self, parser_name)
    for opt in parser.options:
        if opt.flag:
            continue
        default_value = parser.get_default(opt.name)
        if opt.user_optional and values_dict.get(opt.name) == parser.get_default(opt.name) and default_value is not None:
            values_dict[opt.name] = opt.convert(default_value)
        if opt.name in values_dict and values_dict[opt.name] != parser.get_default(opt.name):
            values_dict[opt.name] = opt.convert(values_dict[opt.name])

